def transform(grid):
    h, w = len(grid), len(grid[0])

    # Uniform full rows and columns are the dividers.
    sep_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    sep_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}

    row_bands = []
    start = 0
    for r in sorted(sep_rows):
        if start < r:
            row_bands.append(list(range(start, r)))
        start = r + 1
    if start < h:
        row_bands.append(list(range(start, h)))

    col_bands = []
    start = 0
    for c in sorted(sep_cols):
        if start < c:
            col_bands.append(list(range(start, c)))
        start = c + 1
    if start < w:
        col_bands.append(list(range(start, w)))

    # The most common color away from divider lines is the background.
    from collections import Counter
    counts = Counter(
        grid[r][c]
        for r in range(h) if r not in sep_rows
        for c in range(w) if c not in sep_cols
    )
    background = counts.most_common(1)[0][0]

    result = []
    for rows in row_bands:
        out_row = []
        for cols in col_bands:
            marks = sum(
                grid[r][c] != background
                for r in rows for c in cols
            )
            out_row.append(1 if marks >= 2 else background)
        result.append(out_row)
    return result
